import { afterEach, expect, it } from 'vitest';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { bugfreeFixture } from '../helpers/native-bugfree.js';
import { ensureCliBuilt } from '../helpers/ensure-cli-built.js';
import { resolveWorkspaceRuntimeRootSync } from '../../domains/workflow-contract/workspace-runtime.js';
import { execFileSync } from 'node:child_process';
import { fixtureAcceptanceReview } from '../helpers/native-builder-acceptance-review.js';

const roots: string[] = [];
afterEach(async () => {
  for (const root of roots.splice(0)) await fs.rm(root, { recursive: true, force: true });
});

it('submits the typed receipt template through the public CLI without rebuilding identity fields', async () => {
  await ensureCliBuilt(path.resolve('.'));
  const binary = path.resolve('bin/comet.js');
  const originalTask = 'Produce the expected value without changing the public interface.';
  const fixture = await bugfreeFixture((root) => roots.push(root), binary, originalTask);
  const pending = await fixture.invoke('next', 'bugfree-test');
  const requestFile = path.join(path.dirname(fixture.root), 'opaque-result.json');
  const dispatch = async (request: unknown) => {
    await fs.writeFile(requestFile, JSON.stringify(request));
    return JSON.parse(
      execFileSync(
        process.execPath,
        [
          binary,
          'runtime',
          'dispatch',
          '--application',
          'native',
          '--project-root',
          fixture.root,
          '--request',
          requestFile,
          '--json',
        ],
        { encoding: 'utf8', windowsHide: true, timeout: 30000 },
      ),
    );
  };
  const claimed = await dispatch({
    ...pending.data.pendingAction.claimRequest,
    sessionId: 'public-builder',
  });
  const request = claimed.data.resultRequest;
  expect(claimed.data.originalRequest).toEqual({ source: 'run.input.task', text: originalTask });
  expect(request.result.output).toMatchObject({
    verificationChecks: [],
    acceptanceReview: [{ id: 'A1' }],
  });
  expect(claimed.data.checkRequestTemplate).toMatchObject({
    executable: expect.any(String),
    argv: expect.any(Array),
  });
  await fs.writeFile(path.join(fixture.root, 'value.txt'), 'expected\n');
  request.result.output = {
    ...request.result.output,
    summary: 'Implemented the expected value.',
    acceptanceReview: fixtureAcceptanceReview(['A1']),
    checks: [],
    knownLimits: [],
    verificationChecks: [
      {
        id: 'read-value',
        name: 'Read the final value',
        executable: process.execPath,
        argv: ['-e', "process.stdout.write(require('node:fs').readFileSync('value.txt','utf8'))"],
        cwdRef: '.',
        timeoutMs: 10000,
        repeatable: true,
      },
    ],
  };
  await dispatch(request);
  const accepted = await fixture.inspect();
  expect(accepted.actions.at(-1)).toMatchObject({ stepId: 'verify.checks', status: 'pending' });
  await dispatch(request);
  expect(await fixture.inspect()).toEqual(accepted);
  const review = await fixture.invoke('next', 'bugfree-test');
  const reviewer = await dispatch({
    ...review.data.pendingAction.claimRequest,
    sessionId: 'public-reviewer',
  });
  expect(reviewer.data.resultRequest.result.output.response.result.requestReview).toMatchObject({
    result: '<aligned|conflict|blocked>',
  });
  await dispatch(reviewer.data.refreshChecksResultRequest);
  await fixture.invoke('next', 'bugfree-test');
  const refreshed = await fixture.inspect();
  expect(refreshed.actions.at(-1)).toMatchObject({ stepId: 'verify.verifier', status: 'pending' });
  expect(
    refreshed.actions.filter((action) => action.stepId === 'verify.requested-checks'),
  ).toHaveLength(1);
  const continuation = await fixture.invoke('next', 'bugfree-test');
  const resumed = await dispatch({
    ...continuation.data.pendingAction.claimRequest,
    sessionId: 'public-reviewer',
  });
  const finalRequest = resumed.data.resultRequest;
  finalRequest.result.output.response.result = {
    ...finalRequest.result.output.response.result,
    verdict: 'pass',
    passedAcceptanceIds: ['A1'],
    acceptance: [],
    risks: [],
    summary: 'The original request, Spec and current value agree.',
    requestReview: {
      result: 'aligned',
      reason: 'The expected value is implemented and the public interface remains unchanged.',
    },
  };
  await dispatch(finalRequest);
  expect((await fixture.inspect()).state).toMatchObject({ verification_result: 'pass' });
}, 90000);

it('runs public CLI claims, requested checks, compact results, cold recovery and acceptance', async () => {
  await ensureCliBuilt(path.resolve('.'));
  const fixture = await bugfreeFixture((root) => roots.push(root), path.resolve('bin/comet.js'));
  let run = await fixture.candidate('expected\n');
  const status = await fixture.invoke('status', 'bugfree-test');
  expect(status.data).toMatchObject({ verifyMode: 'bugfree' });
  let state = run.state as {
    builder_handoff: { candidate_id: string };
    loop: { iteration: number; attempt: number };
  };
  await fixture.submit(
    {
      candidateId: state.builder_handoff.candidate_id,
      verifierExecutionRef: 'external-reviewer',
      response: {
        kind: 'request-checks',
        iteration: state.loop.iteration,
        attempt: state.loop.attempt,
        checks: [
          {
            id: 'actual-value',
            name: 'Read actual value',
            executable: process.execPath,
            argv: [
              '-e',
              "if(require('node:fs').readFileSync('value.txt','utf8')!=='expected\\n')process.exit(1)",
            ],
            cwdRef: '.',
            timeoutMs: 10000,
            repeatable: true,
          },
        ],
      },
    },
    'external-reviewer',
  );
  await fixture.invoke('next', 'bugfree-test');
  run = await fixture.inspect();
  state = run.state;
  await fixture.submit(
    {
      candidateId: state.builder_handoff.candidate_id,
      verifierExecutionRef: 'external-reviewer',
      response: {
        kind: 'final-result',
        result: {
          iteration: state.loop.iteration,
          attempt: state.loop.attempt,
          verdict: 'pass',
          passedAcceptanceIds: ['A1'],
          acceptance: [],
          risks: [],
          summary: 'Verified final value.',
        },
      },
    },
    'external-reviewer',
  );
  await fixture.invoke('next', 'bugfree-test');
  const report = await fs.readFile(path.join(fixture.change, 'verification.md'), 'utf8');
  expect(report).toContain('bugfree');
  expect(report).toContain('本轮实际执行');
  expect(report).toContain('actual-value');
  const final = await fixture.inspect();
  expect(final.waits.at(-1)?.stepId).toBe('verify.confirm');
  expect(final.status).toBe('waiting');
  const reviewerIds = final.actions
    .filter((action: { stepId: string }) => action.stepId === 'verify.verifier')
    .map((action: { id: string }) => action.id);
  const runtimeRoot = resolveWorkspaceRuntimeRootSync(fixture.root);
  expect(path.relative(process.env.COMET_DATA_DIR!, runtimeRoot).startsWith('..')).toBe(false);
  for (const directory of ['sdk-runs', 'applications', 'change-owners', 'state-projections'])
    await fs.rm(path.join(runtimeRoot, directory), { recursive: true, force: true });
  await expect(fixture.invoke('status', 'bugfree-test')).rejects.toThrow('checkpoint recovery');
  await fixture.invoke('doctor', 'bugfree-test', '--repair', '--confirmed');
  const restored = await fixture.inspect();
  expect(restored.input.verifyMode).toBe('bugfree');
  expect(
    restored.actions
      .filter((action: { stepId: string }) => action.stepId === 'verify.verifier')
      .map((action: { id: string }) => action.id),
  ).toEqual(reviewerIds);
  const wait = restored.waits.find(
    (entry: { stepId: string; status: string }) =>
      entry.stepId === 'verify.confirm' && entry.status === 'pending',
  );
  await fixture.invoke(
    'next',
    'bugfree-test',
    '--accept-result',
    '--summary',
    'Simulated fixture user accepts this result',
    '--proposal-hash',
    wait.proposalHash,
    '--expected-state-version',
    String(restored.state.state_version),
    '--expected-action',
    'accept-result',
  );
  const accepted = await fixture.inspect();
  expect(accepted.state.phase).toBe('archive');
  expect(accepted.waits.find((entry: { id: string }) => entry.id === wait.id).decision.choice).toBe(
    'approved',
  );
}, 180000);

import { afterEach, expect, it } from 'vitest';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { ensureCliBuilt } from '../../helpers/ensure-cli-built.js';
import { bugfreeFixture } from '../../helpers/native-bugfree.js';
import {
  nativeVerifierContext,
  nativeVerifierReviewInput,
} from '../../../domains/comet-native/native-verifier-context.js';
import { projectNativeSdkDispatchResult } from '../../../domains/comet-native/native-sdk-continuation.js';
import { loadOwnedNativeSdkRuntime } from '../../../domains/comet-native/native-runtime-ownership.js';
import { nativeProjectPaths } from '../../../domains/comet-native/native-paths.js';
import { nativeEditReviewScope } from '../../../domains/comet-native/native-edit-review.js';
import {
  prepareObservedEditReview,
  prepareEditReview,
  recordEditReview,
} from '../../../domains/workflow-contract/edit-review.js';
import { nativeFormalEditReviewScope } from '../../../domains/comet-native/native-edit-review.js';
import { runNativeEditReviewCommand } from '../../../domains/comet-native/native-edit-review-command.js';
import { projectNativeSdkContinuation } from '../../../domains/comet-native/native-sdk-continuation.js';
import { nativeVerifyMode } from '../../../domains/comet-native/native-verification-policy.js';
import {
  writeProjectConfig,
  defaultProjectConfig,
} from '../../../domains/comet-native/native-config.js';
import type { WorkflowRun, RuntimeValue } from '../../../domains/engine/runtime.js';
import type { NativePortableState } from '../../../domains/comet-native/native-portable-types.js';

const roots: string[] = [];
afterEach(async () => {
  for (const root of roots.splice(0)) await fs.rm(root, { recursive: true, force: true });
});

it.each(['runtime', 'public-cli'])(
  'delivers current review material once on claim and refuses material from changed bytes through %s',
  async (boundary) => {
    if (boundary === 'public-cli') await ensureCliBuilt(path.resolve('.'));
    const fixture = await bugfreeFixture(
      (root) => roots.push(root),
      boundary === 'public-cli' ? path.resolve('bin/comet.js') : undefined,
      undefined,
      'bugfree',
      { 'docs/AGENTS.md': 'Preserve the approved value requirement.\n' },
    );
    const content = '\uFEFFexpected\n';
    const run = await fixture.candidate(content);
    const action = run.actions.at(-1)!;
    const pendingView =
      boundary === 'public-cli'
        ? (await fixture.invoke('status', 'bugfree-test')).data
        : await projectNativeSdkContinuation({
            run,
            state: run.state as unknown as NativePortableState,
            projectRoot: fixture.root,
          });
    const dispatched = pendingView.pendingActions.find(
      (entry: { stepId: string }) => entry.stepId === 'verify.verifier',
    );
    expect(dispatched.sessionRequirements).toMatchObject({ independent: true, readOnly: true });
    expect(dispatched.sessionRequirements.instruction).toContain('前台等待');
    expect(dispatched.sessionRequirements.instruction).toContain('已有完整响应文件');
    expect(dispatched.verificationContext.instruction).toMatch(
      /^领取后先读响应中的 data.reviewInput/,
    );
    const owned = await loadOwnedNativeSdkRuntime(fixture.root, 'bugfree-test');
    const request = {
      runId: run.runId,
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      executorId: 'native-host',
      sessionId: 'reader',
      claimToken: 'material-reader',
    };
    let projection: Awaited<ReturnType<typeof projectNativeSdkDispatchResult>>;
    let claimed: WorkflowRun;
    if (boundary === 'public-cli') {
      const file = path.join(path.dirname(fixture.root), 'material-claim.json');
      await fs.writeFile(file, JSON.stringify({ operation: 'claim', ...request }));
      projection = JSON.parse(
        execFileSync(
          process.execPath,
          [
            path.resolve('bin/comet.js'),
            'runtime',
            'dispatch',
            '--application',
            'native',
            '--project-root',
            fixture.root,
            '--request',
            file,
            '--json',
          ],
          { encoding: 'utf8', windowsHide: true, maxBuffer: 16 * 1024 * 1024 },
        ),
      ).data;
      claimed = await fixture.inspect();
    } else {
      claimed = await owned.runtime.claim({
        ...request,
        context: { projectRoot: fixture.root, requestId: 'material-reader' },
      });
      projection = await projectNativeSdkDispatchResult({
        run: claimed,
        state: claimed.state as unknown as NativePortableState,
        actionId: action.id,
        projectRoot: fixture.root,
      });
    }
    expect(projection.reviewInput?.status).toBe('complete');
    expect(projection.activeActions?.find((entry) => entry.id === action.id)).toMatchObject({
      inputRef: 'action.input',
      reviewInputRef: 'reviewInput',
      resultRequestRef: 'resultRequest',
      outcomeRequestRef: 'outcomeRequest',
    });
    expect(projection.reviewInput?.checkInput).toMatchObject({
      candidateStatus: 'unchanged',
      evidenceStatus: 'current',
    });
    expect(projection.acceptanceResultTemplate).toEqual({
      id: '<failed-or-blocked-acceptance-id>',
      result: '<failed|blocked>',
      reason: '<observed-failure-or-blocker>',
    });
    const fields = Object.keys(projection);
    expect(fields.indexOf('resultRequest')).toBeLessThan(fields.indexOf('reviewInput'));
    expect(fields.indexOf('outcomeTemplateInstruction')).toBeLessThan(
      fields.indexOf('reviewInput'),
    );
    expect(projection.reviewInput?.files).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ path: 'value.txt', content }),
        expect.objectContaining({
          path: 'docs/AGENTS.md',
          content: 'Preserve the approved value requirement.\n',
        }),
        expect.objectContaining({
          path: 'docs/comet/changes/bugfree-test/brief.md',
          content: expect.stringContaining('# Outcome'),
        }),
        expect.objectContaining({
          path: 'docs/comet/changes/bugfree-test/specs/value/spec.md',
          content: expect.stringContaining('# Value'),
        }),
      ]),
    );
    expect(JSON.stringify(projection).split(JSON.stringify(content))).toHaveLength(2);
    expect((await fixture.inspect()).revision).toBe(claimed.revision);
    const context = await nativeVerifierContext(claimed, claimed.actions.at(-1)!, fixture.root);
    await fs.writeFile(path.join(fixture.root, 'value.txt'), 'changed after context\n');
    const stale = await nativeVerifierReviewInput(context!);
    expect(stale.status).toBe('incomplete');
    expect(stale.files).not.toEqual(
      expect.arrayContaining([
        expect.objectContaining({ path: 'value.txt', content: expect.any(String) }),
      ]),
    );
    await expect(fixture.submit(final(claimed, 'reader'), 'reader')).rejects.toThrow();
  },
);

it.each(['runtime', 'public-cli'])(
  'does not require absent project instructions and observes newly added rules through %s',
  async (boundary) => {
    if (boundary === 'public-cli') await ensureCliBuilt(path.resolve('.'));
    const fixture = await bugfreeFixture(
      (root) => roots.push(root),
      boundary === 'public-cli' ? path.resolve('bin/comet.js') : undefined,
    );
    const run = await fixture.candidate('expected\n');
    const action = run.actions.at(-1)!;
    const context = async () =>
      boundary === 'public-cli'
        ? (
            (await fixture.invoke('status', 'bugfree-test')).data as {
              pendingActions: Array<{
                verificationContext: Awaited<ReturnType<typeof nativeVerifierContext>>;
              }>;
            }
          ).pendingActions[0].verificationContext
        : nativeVerifierContext(run, action, fixture.root);
    const before = await context();
    expect(before?.requirementRefs).not.toContain('AGENTS.md');
    await fs.writeFile(path.join(fixture.root, 'AGENTS.md'), 'Review the actual value.\n');
    const after = await context();
    expect(after?.requirementRefs).toContain('AGENTS.md');
    expect(after?.checkInput.changes).toEqual(
      expect.arrayContaining([expect.objectContaining({ path: 'AGENTS.md' })]),
    );
    expect(after?.checkInput.candidateStatus).toBe('changed');
    expect((await fixture.inspect()).actions.at(-1)?.status).toBe('pending');
  },
);

it.each(['runtime', 'public-cli'])(
  'surfaces an unapplied formal edit before dispatching a bugfree verifier through %s',
  async (boundary) => {
    if (boundary === 'public-cli') await ensureCliBuilt(path.resolve('.'));
    const fixture = await bugfreeFixture(
      (root) => roots.push(root),
      boundary === 'public-cli' ? path.resolve('bin/comet.js') : undefined,
    );
    const run = await fixture.candidate('expected\n');
    const state = run.state as unknown as NativePortableState;
    const paths = await nativeProjectPaths(fixture.root, 'docs');
    const ref = 'docs/comet/changes/bugfree-test/brief.md';
    const original = await fs.readFile(path.join(fixture.root, ref), 'utf8');
    const scope = { ...nativeFormalEditReviewScope(paths, state), allowedFormalPaths: [ref] };
    const proposal = await prepareEditReview(scope, {
      intent: 'write',
      toolName: 'Write',
      targets: [ref],
      writes: [{ path: ref, content: original + '\nA formatting explanation.\n' }],
    });
    await recordEditReview(
      scope,
      {
        proposalHash: proposal.proposalHash,
        decision: 'non-behavioral',
        summary: 'The explanation preserves every requirement and acceptance item.',
      },
      { kind: 'runtime-agent', executionRef: 'builder' },
    );
    const prepared = (
      boundary === 'public-cli'
        ? JSON.parse(
            execFileSync(
              process.execPath,
              [
                path.resolve('bin/comet.js'),
                'edit-review',
                'prepare-applied',
                'native',
                state.name,
                '--session',
                'builder',
                '--project-root',
                fixture.root,
                '--json',
              ],
              { encoding: 'utf8', windowsHide: true },
            ),
          ).data
        : await runNativeEditReviewCommand({
            projectRoot: fixture.root,
            name: state.name,
            operation: 'prepare-applied',
            sessionId: 'builder',
          })
    ) as { reviews: Array<{ proposalHash: string }>; continuation: unknown };
    expect(prepared.reviews).toEqual(
      expect.arrayContaining([expect.objectContaining({ proposalHash: proposal.proposalHash })]),
    );
    expect(prepared.continuation).not.toBeNull();
    const projection =
      boundary === 'public-cli'
        ? ((await fixture.invoke('status', state.name)).data as Awaited<
            ReturnType<typeof projectNativeSdkContinuation>
          >)
        : await projectNativeSdkContinuation({ run, state, projectRoot: fixture.root });
    expect(projection.continuation.action).toBe('review-edit');
    const pending = projection.pendingActions?.find((entry) => entry.stepId === 'verify.verifier');
    expect(pending?.claimRequest).toBeUndefined();
    expect(pending?.sessionRequirements).toBeUndefined();
    expect(await fs.readFile(path.join(fixture.root, ref), 'utf8')).toBe(original);
    expect((await fixture.inspect()).actions.at(-1)?.status).toBe('pending');
    await expect(fixture.submit(final(run, 'reviewer'), 'reviewer')).rejects.toThrow(
      new RegExp(`${ref.replaceAll('.', '\\.')}.*${proposal.proposalHash}`),
    );
    await recordEditReview(
      scope,
      {
        proposalHash: proposal.proposalHash,
        decision: 'discard',
        summary: 'Keep the approved original; the proposed explanation was never written.',
      },
      { kind: 'runtime-agent', executionRef: 'builder' },
    );
    const ready = await fixture.inspect();
    const resumed = await projectNativeSdkContinuation({
      run: ready,
      state: ready.state as unknown as NativePortableState,
      projectRoot: fixture.root,
    });
    expect(resumed.continuation.action).not.toBe('review-edit');
    await fixture.submit(final(ready, 'reviewer'), 'reviewer');
    expect((await fixture.inspect()).state).toMatchObject({ verification_result: 'pass' });
  },
);

it('pins mode, captures the complete change and passes without inventing command checks', async () => {
  const fixture = await bugfreeFixture((root) => roots.push(root));
  await writeProjectConfig(fixture.root, defaultProjectConfig('docs', 'zh-CN'));
  let run = await fixture.candidate('expected\n');
  expect(nativeVerifyMode(run)).toBe('bugfree');
  const action = run.actions.at(-1)!;
  expect(action.stepId).toBe('verify.verifier');
  const context = await nativeVerifierContext(run, action, fixture.root);
  expect(context?.session.strategy).toBe('fresh');
  expect(context?.changeRefs).toMatchObject({
    complete: true,
    fullChanges: expect.arrayContaining([expect.objectContaining({ path: 'value.txt' })]),
  });
  expect(context?.acceptance).toHaveLength(1);
  const state = run.state as {
    builder_handoff: { candidate_id: string };
    loop: { iteration: number; attempt: number };
  };
  await fixture.submit(
    {
      candidateId: state.builder_handoff.candidate_id,
      verifierExecutionRef: 'reviewer',
      response: {
        kind: 'final-result',
        result: {
          iteration: state.loop.iteration,
          attempt: state.loop.attempt,
          verdict: 'pass',
          passedAcceptanceIds: ['A1'],
          acceptance: [],
          risks: [],
          summary: 'Read final value and requirements.',
        },
      },
    },
    'reviewer',
  );
  await fixture.invoke('next', 'bugfree-test');
  const report = await fs.readFile(path.join(fixture.change, 'verification.md'), 'utf8');
  expect(report).toContain('bugfree');
  expect(report).toContain('本轮未执行命令检查');
  run = await fixture.inspect();
  expect(run.status).toBe('waiting');
  expect(run.waits.at(-1)?.stepId).toBe('verify.confirm');
});

function final(run: WorkflowRun, sessionId: string, verdict = 'pass'): RuntimeValue {
  const state = run.state as {
    builder_handoff: { candidate_id: string };
    loop: { iteration: number; attempt: number };
  };
  return {
    candidateId: state.builder_handoff.candidate_id,
    verifierExecutionRef: sessionId,
    response: {
      kind: 'final-result',
      result: {
        iteration: state.loop.iteration,
        attempt: state.loop.attempt,
        verdict,
        passedAcceptanceIds: verdict === 'pass' ? ['A1'] : [],
        acceptance:
          verdict === 'pass' ? [] : [{ id: 'A1', result: 'failed', reason: 'The value is wrong.' }],
        risks: [],
        summary: 'Read the final value and caller.',
      },
    },
  };
}

it.each(['standard', 'bugfree'] as const)(
  'binds the original task and rejects a passing review that omits or contradicts it in %s',
  async (mode) => {
    const task = 'Recover the original operation after a disconnect; keep the public interface.';
    const fixture = await bugfreeFixture((root) => roots.push(root), undefined, task, mode);
    const run = await fixture.candidate('expected\n');
    expect(run.input).toMatchObject({ task });
    const context = await nativeVerifierContext(run, run.actions.at(-1)!, fixture.root);
    const dispatchView = await projectNativeSdkContinuation({
      run,
      state: run.state as unknown as NativePortableState,
      projectRoot: fixture.root,
    });
    const dispatched = dispatchView.pendingActions.find(
      (entry) => entry.stepId === 'verify.verifier',
    );
    expect(dispatched?.sessionRequirements).toMatchObject({ independent: true, readOnly: true });
    if (mode === 'standard')
      expect(dispatched?.sessionRequirements?.instruction).not.toContain('前台等待');
    if (mode === 'bugfree')
      expect(context).toMatchObject({ originalRequest: { source: 'run.input.task', text: task } });
    const review = (current: typeof run) => {
      const output = final(current, 'reviewer');
      if (mode === 'standard') {
        const result = output.response.result as Record<string, unknown>;
        delete result.passedAcceptanceIds;
        result.acceptance = [{ id: 'A1', result: 'passed', reason: 'Read the implementation.' }];
      }
      return output;
    };
    await expect(fixture.submit(review(run), 'reviewer')).rejects.toThrow(/requestReview/);
    const contradicted = review(await fixture.inspect());
    (contradicted.response.result as Record<string, unknown>).requestReview = {
      result: 'conflict',
      reason: 'The Spec excludes recovery required by the original task.',
    };
    await expect(fixture.submit(contradicted, 'reviewer')).rejects.toThrow(/requestReview/);
    (contradicted.response.result as Record<string, unknown>).requestReview = {
      result: 'blocked',
      reason: 'The original requirement remains unclear.',
    };
    await expect(fixture.submit(contradicted, 'reviewer')).rejects.toThrow(/requestReview/);
    const aligned = review(await fixture.inspect());
    (aligned.response.result as Record<string, unknown>).requestReview = {
      result: 'aligned',
      reason: 'Compared the original task, authorized scope and actual implementation.',
    };
    await fixture.submit(aligned, 'reviewer');
